function only<T>(values:Partial<T>):T{return new Proxy(values,{get(target,name){if(name in target)return Reflect.get(target,name);throw Error(`Unexpected port ${String(name)}`);}}) as T;}
const actor={userId:"operator",assignmentId:"authority",sessionId:"session",companyId:"company",platform:false} as IamActor;
const input=provisioningInput.parse({engagementIds:["engagement"],validUntil:200,reason:"Reviewed provision resources"});
function service(overrides:Partial<TechnologyPorts>={}){return createTechnologyService(only<TechnologyPorts>({now:()=>100,id:()=>"operation",hash:JSON.stringify,error:(s,c,m)=>new ApiError(s,c,m),errorCode:e=>e instanceof ApiError?e.code:undefined,assertCompanyScope:()=>{},authorize:()=>{},fresh:async()=>{},parseGrant:v=>grantInput.parse(v),...overrides}));}
function previewStore(overrides:Partial<TechnologyStore>={}){return only<TechnologyStore>({parentExpiry:async()=>({valid_until:500}),activeApplications:async()=>[],membershipSources:async()=>[],engagement:async()=>({id:"engagement",person_id:"person",company_id:"company",position_id:"position",branch_id:null,department_id:null,version:1,status:"active",person_status:"active",legal_name:"Person",user_id:"user"}),accessCutoff:async()=>0,positionPackage:async()=>({package_id:"package",revision:1}),packageRevision:async()=>({definition:{name:"Pinned package",account:"local",groupIds:[],directoryGroupIds:[],windowsPolicies:[],grants:[],tasks:[]}}),verifiedUsers:async()=>[],...overrides});}
const operation:ProvisionOperation={id:"operation",company_id:"company",created_by:"operator",assignment_id:"authority",session_id:"session",status:"queued",version:1,last_error:null,steps:[],definition:input,evidence:{plans:[],directory:[],inventories:[],sources:[],beforeApps:[]}};
function workerService(store:TechnologyStore,events:string[],override:Partial<TechnologyPorts>={}){return service({due:async()=>[{id:"operation"}],worker:async()=>({store,begin:async()=>{events.push("begin");},commit:async()=>{events.push("commit");},rollback:async()=>{events.push("rollback");},release:()=>{events.push("release");}}),...override});}
it("requires live company scope and permission before any read or command replay",async()=>{await expect(service().technologyData({...actor,platform:true})).rejects.toMatchObject({code:"COMPANY_SCOPE_REQUIRED"});const command=vi.fn();await expect(service({authorize:()=>{throw new ApiError(403,"FORBIDDEN","Revoked.");},command}).applyProvisioning(actor,input,"token","key")).rejects.toMatchObject({code:"FORBIDDEN"});expect(command).not.toHaveBeenCalled();});
it("keeps preview on the provided repeatable-read transaction and pins package facts in the digest",async()=>{const store=previewStore();const result=await service({preview:async run=>run(store)}).previewProvisioning(actor,input);expect(result.employees).toMatchObject([{id:"engagement",name:"Person",packageName:"Pinned package",revision:1,reviews:0}]);expect(JSON.parse(result.token)).toMatchObject({input,evidence:{plans:[{engagementVersion:1,packageId:"package",revision:1}]}});});
it("rejects expiry outside delegated authority without reading person facts",async()=>{const store=only<TechnologyStore>({parentExpiry:async()=>({valid_until:150})});await expect(service({preview:async run=>run(store)}).previewProvisioning(actor,input)).rejects.toMatchObject({code:"PROVISIONING_CHANGED"});});
it("requires completed HR placement before resources can be applied",async()=>{const store=previewStore({engagement:async()=>undefined});await expect(service({preview:async run=>run(store)}).previewProvisioning(actor,input)).rejects.toMatchObject({code:"PLACEMENT_REQUIRED"});});
it("does not restore suspended employee access from an old placement",async()=>{const store=previewStore({accessCutoff:async()=>1});await expect(service({preview:async run=>run(store)}).previewProvisioning(actor,input)).rejects.toMatchObject({code:"ACCESS_CUTOFF_ACTIVE"});});
it("requires current published package facts",async()=>{const store=previewStore({positionPackage:async()=>undefined});await expect(service({preview:async run=>run(store)}).previewProvisioning(actor,input)).rejects.toMatchObject({code:"PACKAGE_REQUIRED"});});
it("retains command receipt replay without opening a new mutation unit",async()=>{const prior={id:"prior",status:"queued",reviews:[]};expect(await service({command:async<Result>()=>prior as Result}).applyProvisioning(actor,input,"token","key")).toEqual(prior);});
it("rejects changed preview before staging any operation effects",async()=>{const store=previewStore();await expect(service({command:async(_a,_k,_o,_p,_perm,run)=>run(store)}).applyProvisioning(actor,input,"old-token","key")).rejects.toMatchObject({code:"PREVIEW_CHANGED"});});
it("prevents a second in-progress operation for the selected person",async()=>{const store=previewStore({personInProgress:async()=>1}),s=service({preview:async run=>run(store),command:async(_a,_k,_o,_p,_perm,run)=>run(store)}),p=await s.previewProvisioning(actor,input);await expect(s.applyProvisioning(actor,input,p.token,"key")).rejects.toMatchObject({code:"PROVISIONING_CHANGED"});});
it("keeps preparation and applied package writes inside the same command transaction",async()=>{const events:string[]=[];const store=previewStore({personInProgress:async()=>0,createOperation:async()=>{events.push("operation");},applyPackage:async()=>{events.push("package");},saveSteps:async()=>{events.push("steps");}}),s=service({preview:async run=>run(store),command:async(_a,_k,_o,_p,_perm,run)=>run(store)}),p=await s.previewProvisioning(actor,input);expect(await s.applyProvisioning(actor,input,p.token,"key")).toEqual({id:"operation",status:"queued",reviews:[]});expect(events).toEqual(["operation","package","steps"]);});
it("defers a busy shared Directory lease without marking work failed",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:false})}),events).drainProvisioning();expect(events).toEqual(["begin","commit","release"]);});
it("rolls back an operation already claimed by another worker",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:true}),lockedOperation:async()=>undefined}),events).drainProvisioning();expect(events).toEqual(["begin","rollback","release"]);});
it("persists child delivery state before committing without applying package resources",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:true}),lockedOperation:async()=>operation,directoryChildren:async()=>[{id:"child",status:"blocked",last_error:"provider-error"}],recordChildrenState:async()=>{events.push("children");}}),events).drainProvisioning();expect(events).toEqual(["begin","children","commit","release"]);});
it("keeps completion, outbox and audit in one worker commit",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:true}),lockedOperation:async()=>operation,directoryChildren:async()=>[],operatorAuthority:async()=>1,completeOperation:async()=>{events.push("complete");},appendAppliedOutbox:async()=>{events.push("outbox");},appendAppliedAudit:async()=>{events.push("audit");}}),events).drainProvisioning();expect(events).toEqual(["begin","complete","outbox","audit","commit","release"]);});
it("rolls back failed completion before writing the separate durable retry journal",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:true}),lockedOperation:async()=>operation,directoryChildren:async()=>[],operatorAuthority:async()=>1,completeOperation:async()=>{events.push("complete");},appendAppliedOutbox:async()=>{throw Error("Lost completion response");},recordBlockedOperation:async({reason})=>{events.push(reason);}}),events).drainProvisioning();expect(events).toEqual(["begin","complete","rollback","PROVISIONING_RETRY_REQUIRED","release"]);});
it("blocks revoked operator authority before package changes and preserves its specific retry reason",async()=>{const events:string[]=[];await workerService(only<TechnologyStore>({sharedDirectoryLease:async()=>({available:true}),lockedOperation:async()=>operation,directoryChildren:async()=>[],operatorAuthority:async()=>0,recordBlockedOperation:async({reason})=>{events.push(reason);}}),events).drainProvisioning();expect(events).toEqual(["begin","rollback","PROVISIONING_AUTHORITY_CHANGED","release"]);});
const grant:ProvisionGrant={id:"grant",assignment_id:null,ended_at:null,status:"queued",company_id:"company",person_id:"person",definition:grantInput.parse({userId:"user",roleId:"employee",scopeKind:"holding",scopeNodeId:null,validUntil:200,reason:"Independent provisioning"})};
it("rejecting a role leaves HR placement and unrelated resources intact",async()=>{await service().applyProvisioningReview(only<TechnologyStore>({lockedGrant:async()=>grant}),actor,{grantId:"grant"},"reject");});
it("denies self review before validating or creating grants",async()=>{await expect(service().applyProvisioningReview(only<TechnologyStore>({lockedGrant:async()=>grant,reviewerIsPerson:async()=>({same:true})}),actor,{grantId:"grant"})).rejects.toMatchObject({code:"SELF_ACCESS_CHANGE"});});
it("requires the verified account link to remain current at independent approval",async()=>{await expect(service().applyProvisioningReview(only<TechnologyStore>({lockedGrant:async()=>grant,reviewerIsPerson:async()=>({same:false}),grantUserIsPerson:async()=>({ok:false})}),actor,{grantId:"grant"})).rejects.toMatchObject({code:"PROVISIONING_CHANGED"});});
it("retries only the same operator's interrupted version with fresh authority",async()=>{const store=only<TechnologyStore>({retryOperation:async()=>({...operation,status:"blocked",last_error:"PROVISIONING_AUTHORITY_CHANGED"})});await expect(service({command:async(_a,_k,_o,_p,_perm,run)=>run(store)}).retryProvisioning(actor,"operation",1,"key")).rejects.toMatchObject({code:"PROVISIONING_CHANGED"});});

