 const env=positionEnvironment(),late=latePositionJson({token:'native-preview-token',people:['Actual employee'],definition:positionRecipe});let source=positionSource();const send=vi.fn<typeof workFetch>().mockResolvedValueOnce(late.response).mockResolvedValueOnce(Response.json({data:{token:'native-preview-token',people:['Actual employee'],definition:positionRecipe}})),commands=createPositionBindingCommands(()=>source,send);
