function positionElements(node:ReactNode):ReactElement<Record<string,unknown>>[]{if(!isValidElement<Record<string,unknown>>(node))return [];return [node,...Children.toArray(node.props.children as ReactNode).flatMap(child=>positionElements(child))];}
function positionText(node:ReactNode):string{return typeof node==='string'||typeof node==='number'?String(node):isValidElement<{children?:ReactNode}>(node)?Children.toArray(node.props.children).map(positionText).join(''):'';}
function positionElement(tree:ReactNode,match:(node:ReactElement<Record<string,unknown>>)=>boolean){const found=positionElements(tree).find(match);if(!found)throw Error('Actual standard Position control required');return found;}
